const parents=['F:/','F:/Dev',root,run,temp],parentStates=[];
async function parent(p,required){check();const s=await stat(p);if((required&&!s)||(s&&(s.isSymbolicLink()||!s.isDirectory())))throw error('unsafe-parent');parentStates.push([p,s?String(s.dev)+':'+String(s.ino):null]);}
for(const p of parents)await parent(p,true);
const entries=await names(),matches=entries.filter(n=>/^scotty-tray-smoke-[0-9a-f]{32}$/.test(n));if(matches.length!==1)throw error('expected-one-smoke-directory');
const selected=temp+'/'+matches[0];await parent(selected,true);
const cases=['exit','parent-loss'],paths=cases.map(n=>selected+'/'+n+'/processes.jsonl');for(const n of cases)await parent(selected+'/'+n,false);
